import pickle
import numpy as np
import os, sys, warnings
warnings.filterwarnings('ignore')

class MockEmbedding:
    def __init__(self, *args, **kwargs): pass
    def __setstate__(self, state): self.__dict__.update(state)

class MockGaussianMixtureClustering:
    def __init__(self, *args, **kwargs): pass
    def __setstate__(self, state): self.__dict__.update(state)

class CustomUnpickler(pickle.Unpickler):
    def find_class(self, module, name):
        if module.startswith('flyvis'):
            if 'Embedding' in name: return MockEmbedding
            if 'GaussianMixtureClustering' in name: return MockGaussianMixtureClustering
            if 'Clustering' in name: return MockGaussianMixtureClustering
        if module == 'numpy.core.multiarray' and name == '_reconstruct':
            return np._core.multiarray._reconstruct
        if module == 'numpy' and name == 'ndarray': return np.ndarray
        if module == 'numpy' and name == 'dtype': return np.dtype
        try:
            return super().find_class(module, name)
        except:
            return type('Mock', (), {})

pickle_dir = 'data/flow/0000/umap_and_clustering/'
cell_types = sorted([f.replace('.pickle', '') for f in os.listdir(pickle_dir) if f.endswith('.pickle')])

all_embeddings = {}
all_labels = {}
all_cluster_info = {}

for ct in cell_types:
    path = os.path.join(pickle_dir, f'{ct}.pickle')
    with open(path, 'rb') as f:
        data = CustomUnpickler(f).load()
    all_embeddings[ct] = data.embedding._embedding.copy()
    all_labels[ct] = data.labels.copy()
    all_cluster_info[ct] = {
        'n_clusters': len(np.unique(data.labels)),
        'means': data.gm.means_.copy(),
        'weights': data.gm.weights_.copy()
    }

print(f'Loaded {len(cell_types)} cell types')
print(f'Cell types: {cell_types}')

# Save all data
np.savez('outputs/cell_type_data.npz', 
         cell_types=np.array(cell_types),
         **{f'emb_{ct}': all_embeddings[ct] for ct in cell_types},
         **{f'labels_{ct}': all_labels[ct] for ct in cell_types})

import json
with open('outputs/cell_type_list.json', 'w') as f:
    json.dump(cell_types, f)

with open('outputs/cluster_info.json', 'w') as f:
    json.dump({ct: {k: v.tolist() if hasattr(v, 'tolist') else v for k,v in info.items()} 
               for ct, info in all_cluster_info.items()}, f, indent=2)

print('Saved cell type data')
